}
const uniq=[...new Set(items.map(i=>i.pmid))];
console.log('total PMID mentions:',items.length,'unique:',uniq.length);

(async()=>{
  const out={};
  for(let i=0;i<uniq.length;i+=80){
    const batch=uniq.slice(i,i+80);
    const url=`https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&id=${batch.join(',')}&retmode=json`;
    const r=await fetch(url); const j=await r.json();
    for(const id of batch){
      const rec=j.result&&j.result[id];
      if(!rec||rec.error){out[id]={err:'NOT FOUND'};continue;}
      out[id]={title:rec.title||'',auth:(rec.sortfirstauthor||''),yr:(rec.pubdate||'').slice(0,4),src:rec.source||''};
    }
    await new Promise(s=>setTimeout(s,400));
  }
  // compare
  const problems=[];
  for(const it of items){
    const rec=out[it.pmid];
    if(!rec){problems.push(`${it.pmid} :: no record`);continue;}
    if(rec.err){problems.push(`${it.pmid} :: NOT FOUND IN PUBMED :: cited as "${it.ctx.slice(-110)}"`);continue;}
    // surname of first author as I cited it: look for capitalised word before initials or "et al"
    const surnameFromRec=(rec.auth||'').split(' ')[0].toLowerCase().replace(/[^a-z]/g,'');
    const ctxLow=it.ctx.toLowerCase();
    const surnameOk = surnameFromRec.length>2 && ctxLow.includes(surnameFromRec);
    // year check
    const yearOk = rec.yr && it.ctx.includes(rec.yr);
    if(!surnameOk||!yearOk){
      problems.push(`PMID ${it.pmid} | pubmed="${rec.auth} ${rec.yr} ${rec.src}: ${rec.title.slice(0,80)}" | surnameMatch=${surnameOk} yearMatch=${yearOk} | cited-as="...${it.ctx.slice(-130)}"`);
    }
  }
  console.log('--- MISMATCHES ('+problems.length+') ---');
  problems.forEach(p=>console.log(p));
  if(problems.length===0) console.log('ALL CLEAN');
})();

